@compute @workgroup_size(2,3,4) fn z_compute() {}
@vertex fn a_vertex() -> @builtin(position) vec4<f32> {return vec4<f32>(0.0);}
@fragment fn m_fragment() -> @location(0) vec4<f32> {return vec4<f32>(1.0);}

struct Params { scale: f32, count: u32, };
@group(0) @binding(0) var<storage,read_write> values: array<f32>;
@group(0) @binding(1) var<uniform> params: Params;
@compute @workgroup_size(4) fn main(@builtin(global_invocation_id) id: vec3<u32>){if(id.x < params.count){values[id.x] *= params.scale;}}
